mapper.select:
SELECT COUNT(1)
FROM PLAYLIST_TRACKS
WHERE PLAYLIST_ID = #{playlistId}
  AND PLAYLIST_TRACK_ID = #{trackId}

mapper.update:
UPDATE PLAYLIST_TRACKS
SET POSITION_NO = #{positionNo}
WHERE PLAYLIST_TRACK_ID = #{trackId}

BEGIN

    UPDATE PLAYLIST_TRACKS
    SET POSITION_NO = #{track.positionNo}
    WHERE PLAYLIST_TRACK_ID = #{track.playlistTrackId}
;
END;
